    return registry_model.search([
        ('x_document_type', '=', 'tor'),
        ('x_source_model', '=', 'hr.applicant'),
        ('x_source_res_id', '=', applicant.id),
    ], order='x_version desc, id desc', limit=1) or registry_model.search([
        ('x_document_type', '=', 'tor'),
        ('x_applicant_id', '=', applicant.id),
    ], order='x_version desc, id desc', limit=1)

for rec in records.sudo():
    registry_doc = find_registry(rec)
    certificate = registry_doc.x_sign_certificate_attachment_id

    if not certificate and registry_doc.x_sign_request_res_id:
        certificate = attachment_model.search([
            ('res_model', '=', 'hr.applicant'),
            ('res_id', '=', rec.id),
            ('mimetype', '=', 'application/pdf'),
        ], order='create_date desc, id desc').filtered(lambda att: looks_like_certificate(att))[:1]

    if not certificate:
        action = toast('لا توجد شهادة توقيع', 'لم يتم العثور على شهادة توقيع للوصف الوظيفي. استخدم مزامنة التوقيع أولاً أو راجع مرفقات أودو Sign.', 'warning', False)
        continue

    action = {
        'type': 'ir.actions.act_url',
        'url': '/web/content/%s?download=true' % certificate.id,
        'target': 'self',
    }
    break

if not action:
    action = {'type': 'ir.actions.client', 'tag': 'reload'}
